<?php
declare(strict_types=1);
namespace App\Repositories;
use App\Core\Database;
final class AttendanceRepository{
public function __construct(private readonly Database $db){}
public function students(int$class,string$date,int$institute):array{return$this->db->query("SELECT s.id,s.registration_no,s.student_name,s.status person_status,s.status_changed_at,COALESCE(a.status,'Present') attendance_status,COALESCE(a.remarks,'') remarks FROM students s LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date=:d WHERE s.class_id=:c AND s.institute_id=:i AND (".\App\Support\PersonStatus::visibleSql($this->db,$institute,'student','s','attendance',':since')." OR a.id IS NOT NULL) ORDER BY s.student_name ASC,s.registration_no ASC,s.id ASC",['d'=>$date,'c'=>$class,'i'=>$institute,'since'=>$date.' 00:00:00'])->fetchAll();}
public function allStudents(string$date,int$institute):array{return$this->db->query("SELECT s.id,s.registration_no,s.student_name,s.status person_status,s.status_changed_at,c.name class_name,COALESCE(a.status,'Present') attendance_status,COALESCE(a.remarks,'') remarks FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date=:d WHERE s.institute_id=:i AND (".\App\Support\PersonStatus::visibleSql($this->db,$institute,'student','s','attendance',':since')." OR a.id IS NOT NULL) ORDER BY c.name ASC,s.student_name ASC,s.registration_no ASC,s.id ASC",['d'=>$date,'i'=>$institute,'since'=>$date.' 00:00:00'])->fetchAll();}
public function employees(string$date,int$institute):array{return$this->db->query("SELECT e.id,e.employee_no,e.name,e.role,e.status person_status,e.status_changed_at,COALESCE(a.status,'Present') attendance_status,a.time_in,a.time_out,COALESCE(a.remarks,'') remarks FROM employees e LEFT JOIN employee_attendance a ON a.employee_id=e.id AND a.attendance_date=:d WHERE e.institute_id=:i AND (".\App\Support\PersonStatus::visibleSql($this->db,$institute,'employee','e','attendance',':since')." OR a.id IS NOT NULL) ORDER BY e.name",['d'=>$date,'i'=>$institute,'since'=>$date.' 00:00:00'])->fetchAll();}
public function studentRecords(int$institute,string$from,string$to,int$class=0):array{$where=$class?' AND s.class_id=:class':'';$params=['institute'=>$institute,'from'=>$from,'to'=>$to];if($class)$params['class']=$class;return$this->db->query("SELECT a.attendance_date,s.registration_no,s.student_name,c.name class_name,a.status,a.remarks FROM student_attendance a JOIN students s ON s.id=a.student_id LEFT JOIN classes c ON c.id=s.class_id WHERE s.institute_id=:institute AND a.attendance_date BETWEEN :from AND :to{$where} ORDER BY a.attendance_date DESC,s.student_name ASC,s.registration_no ASC,s.id ASC",$params)->fetchAll();}
public function employeeRecords(int$institute,string$from,string$to):array{return$this->db->query("SELECT a.attendance_date,e.employee_no,e.name,e.role,a.status,a.time_in,a.time_out,a.remarks FROM employee_attendance a JOIN employees e ON e.id=a.employee_id WHERE e.institute_id=:institute AND a.attendance_date BETWEEN :from AND :to ORDER BY a.attendance_date DESC,e.name",['institute'=>$institute,'from'=>$from,'to'=>$to])->fetchAll();}
public function classSummary(int$institute,string$date,int$class=0):array{$where=$class?' AND c.id=:class':'';$p=['i'=>$institute,'d'=>$date,'d2'=>$date,'since'=>$date.' 00:00:00'];if($class)$p['class']=$class;return$this->db->query("SELECT c.id,c.name,COUNT(DISTINCT s.id) student_count,COUNT(a.id) marked,SUM(a.status='Present') present_count,SUM(a.status='Absent') absent_count,SUM(a.status='Late') late_count,SUM(a.status='Leave') leave_count FROM classes c LEFT JOIN students s ON s.class_id=c.id AND (".\App\Support\PersonStatus::visibleSql($this->db,$institute,'student','s','attendance',':since')." OR EXISTS(SELECT 1 FROM student_attendance x WHERE x.student_id=s.id AND x.attendance_date=:d2)) LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date=:d WHERE c.institute_id=:i{$where} GROUP BY c.id,c.name ORDER BY c.name",$p)->fetchAll();}
public function saveStudents(string$date,array$rows,int$user):void{$sql="INSERT INTO student_attendance(student_id,attendance_date,status,remarks,marked_by,created_at,updated_at) VALUES (:id,:date,:status,:remarks,:user,:created,:updated) ON DUPLICATE KEY UPDATE status=VALUES(status),remarks=VALUES(remarks),marked_by=VALUES(marked_by),updated_at=VALUES(updated_at)";$now=date('Y-m-d H:i:s');foreach($rows as$r)$this->db->query($sql,$r+['date'=>$date,'user'=>$user,'created'=>$now,'updated'=>$now]);}
public function saveEmployees(string$date,array$rows,int$user):void{$sql="INSERT INTO employee_attendance(employee_id,attendance_date,status,time_in,time_out,remarks,marked_by,created_at,updated_at) VALUES (:id,:date,:status,:time_in,:time_out,:remarks,:user,:created,:updated) ON DUPLICATE KEY UPDATE status=VALUES(status),time_in=VALUES(time_in),time_out=VALUES(time_out),remarks=VALUES(remarks),marked_by=VALUES(marked_by),updated_at=VALUES(updated_at)";$now=date('Y-m-d H:i:s');foreach($rows as$r)$this->db->query($sql,$r+['date'=>$date,'user'=>$user,'created'=>$now,'updated'=>$now]);}
/** Daily register for every active student (optionally one class), filtered by status ('Not marked' = no record) and name / reg. no. */
public function daily(int$institute,string$date,int$class=0,string$status='',string$search=''):array{$w='';$p=['d'=>$date,'i'=>$institute,'since'=>$date.' 00:00:00'];if($class){$w.=' AND s.class_id=:class';$p['class']=$class;}if($status==='Not marked')$w.=' AND a.id IS NULL';elseif(in_array($status,['Present','Absent','Late','Leave'],true)){$w.=' AND a.status=:status';$p['status']=$status;}if($search!==''){$w.=' AND (s.student_name LIKE :q OR s.registration_no LIKE :q2)';$p['q']='%'.$search.'%';$p['q2']='%'.$search.'%';}return$this->db->query("SELECT s.id,s.registration_no,s.student_name,c.id class_id,c.name class_name,s.status person_status,s.status_changed_at,COALESCE(a.status,'Not marked') attendance_status,COALESCE(a.remarks,'') remarks FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN student_attendance a ON a.student_id=s.id AND a.attendance_date=:d WHERE s.institute_id=:i AND (".\App\Support\PersonStatus::visibleSql($this->db,$institute,'student','s','attendance',':since')." OR a.id IS NOT NULL){$w} ORDER BY c.name ASC,s.student_name ASC,s.registration_no ASC,s.id ASC",$p)->fetchAll();}
public function db():Database{return$this->db;}
}
